<section class="content-section" id="challenges-section">
    <div class="content-container">
        <div class="text-content">
            <h2 class="section-title">Xero Accounting Challenges Specific to Ahmedabad: GIFT City IFSC Regime and GIDC Estate Compliance</h2>
            <div class="content-text">
